package io.tornado.reporting;import io.tornado.config.TelegramProperties;import io.tornado.notification.TelegramNotificationService;import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.client.RestClient;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class DailyTelegramReportServiceTest{@Test void usesPreviousTehranCalendarDayBoundariesAndCrossDayDefinitions(){LocalDate date=LocalDate.of(2026,8,14);Instant start=date.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),end=date.plusDays(1).atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant();var repository=mock(MixTradeSimulationRepository.class);MixTradeSimulation hit=simulation(start.plusSeconds(60));hit.observe(hit.getTargetPrice(),start.plusSeconds(120));MixTradeSimulation open=simulation(end.minusSeconds(60));MixTradeSimulation openedYesterday=simulation(start.minusSeconds(60));openedYesterday.observe(openedYesterday.getTargetPrice(),start.plusSeconds(180));when(repository.findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(start,end)).thenReturn(List.of(hit,open));when(repository.findByClosedAtGreaterThanEqualAndClosedAtLessThan(start,end)).thenReturn(List.of(hit,openedYesterday));when(repository.countByStatus(MixTradeSimulation.Status.OPEN)).thenReturn(1L);var service=service(repository);
 var summary=service.summarize(date);
 assertThat(summary.created()).isEqualTo(2);assertThat(summary.targets()).isEqualTo(2);assertThat(summary.pending()).isEqualTo(1);assertThat(summary.methods()).allSatisfy(m->assertThat(m.executions()).isEqualTo(2));verify(repository).findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(start,end);}
 @Test void emptyDayProducesReadableReportWithoutDividingByOpenTrades(){var repository=mock(MixTradeSimulationRepository.class);when(repository.findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(any(),any())).thenReturn(List.of());when(repository.findByClosedAtGreaterThanEqualAndClosedAtLessThan(any(),any())).thenReturn(List.of());var service=service(repository);String text=service.format(service.summarize(LocalDate.of(2026,8,14)));assertThat(text).contains("Signals Created: 0","Terminal Hit Rate: —","TP MILESTONES","SL MILESTONES","Not enough closed simulations");}
 @Test void sentReportIsIdempotentAndIsNotDeliveredAgain(){LocalDate date=LocalDate.of(2026,8,14);var simulations=mock(MixTradeSimulationRepository.class);var reports=mock(TelegramDailyReportRepository.class);var settings=mock(AppSettingsRepository.class);var telegram=mock(TelegramNotificationService.class);var appSettings=new AppSettings(900,900);appSettings.updateMixSignals(30,new BigDecimal("0.5"),true);var report=new TelegramDailyReport(date,date.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),date.plusDays(1).atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),Instant.now());report.sent(42);when(settings.findById(1)).thenReturn(Optional.of(appSettings));when(telegram.configured()).thenReturn(true);when(reports.findByReportDate(date)).thenReturn(Optional.of(report));new DailyTelegramReportService(simulations,reports,settings,telegram,Clock.systemUTC()).send(date);verify(telegram,never()).send(anyString());verifyNoInteractions(simulations);}
 @Test void failedReportCanRetryAndStopsAfterSuccessfulDelivery(){LocalDate date=LocalDate.of(2026,8,14);var simulations=mock(MixTradeSimulationRepository.class);when(simulations.findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(any(),any())).thenReturn(List.of());when(simulations.findByClosedAtGreaterThanEqualAndClosedAtLessThan(any(),any())).thenReturn(List.of());var reports=mock(TelegramDailyReportRepository.class);var settings=mock(AppSettingsRepository.class);var telegram=mock(TelegramNotificationService.class);var appSettings=new AppSettings(900,900);appSettings.updateMixSignals(30,new BigDecimal("0.5"),true);var report=new TelegramDailyReport(date,date.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),date.plusDays(1).atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),Instant.now());report.failed("temporary");when(settings.findById(1)).thenReturn(Optional.of(appSettings));when(telegram.configured()).thenReturn(true);when(reports.findByReportDate(date)).thenReturn(Optional.of(report));when(reports.findByStatusAndAttemptsLessThanOrderByReportDateAsc(TelegramDailyReport.Status.FAILED,3)).thenReturn(List.of(report));when(telegram.send(anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.SENT,77L,null));var service=new DailyTelegramReportService(simulations,reports,settings,telegram,Clock.systemUTC());service.retryFailed();assertThat(report.getStatus()).isEqualTo(TelegramDailyReport.Status.SENT);assertThat(report.getAttempts()).isEqualTo(2);assertThat(report.getTelegramMessageId()).isEqualTo(77L);service.send(date);verify(telegram,times(1)).send(anyString());}
 @Test void exactTehranMidnightSelectsPreviousCalendarDay(){LocalDate today=LocalDate.of(2026,8,15),previous=today.minusDays(1);Clock clock=Clock.fixed(today.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),ZoneOffset.UTC);var reports=mock(TelegramDailyReportRepository.class);var settings=mock(AppSettingsRepository.class);var telegram=mock(TelegramNotificationService.class);var appSettings=new AppSettings(900,900);appSettings.updateMixSignals(30,new BigDecimal("0.5"),true);var sent=new TelegramDailyReport(previous,previous.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),today.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),clock.instant());sent.sent(9);when(settings.findById(1)).thenReturn(Optional.of(appSettings));when(telegram.configured()).thenReturn(true);when(reports.findByReportDate(previous)).thenReturn(Optional.of(sent));new DailyTelegramReportService(mock(MixTradeSimulationRepository.class),reports,settings,telegram,clock).sendPreviousDay();verify(reports).findByReportDate(previous);verify(telegram,never()).send(anyString());}
 @Test void telegramFailureIsRetainedForAuditAndRetry(){LocalDate date=LocalDate.of(2026,8,14);var simulations=mock(MixTradeSimulationRepository.class);when(simulations.findByOpenedAtGreaterThanEqualAndOpenedAtLessThan(any(),any())).thenReturn(List.of());when(simulations.findByClosedAtGreaterThanEqualAndClosedAtLessThan(any(),any())).thenReturn(List.of());var reports=mock(TelegramDailyReportRepository.class);var settings=mock(AppSettingsRepository.class);var telegram=mock(TelegramNotificationService.class);var appSettings=new AppSettings(900,900);appSettings.updateMixSignals(30,new BigDecimal("0.5"),true);var report=new TelegramDailyReport(date,date.atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),date.plusDays(1).atStartOfDay(DailyTelegramReportService.TEHRAN).toInstant(),Instant.now());when(settings.findById(1)).thenReturn(Optional.of(appSettings));when(telegram.configured()).thenReturn(true);when(reports.findByReportDate(date)).thenReturn(Optional.of(report));when(telegram.send(anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.FAILED,null,"temporary outage"));new DailyTelegramReportService(simulations,reports,settings,telegram,Clock.systemUTC()).send(date);assertThat(report.getStatus()).isEqualTo(TelegramDailyReport.Status.FAILED);assertThat(report.getAttempts()).isEqualTo(1);assertThat(report.getError()).isEqualTo("temporary outage");}
 private DailyTelegramReportService service(MixTradeSimulationRepository repository){return new DailyTelegramReportService(repository,mock(TelegramDailyReportRepository.class),mock(AppSettingsRepository.class),new TelegramNotificationService(new TelegramProperties("",""),RestClient.builder()),Clock.systemUTC());}private MixTradeSimulation simulation(Instant opened){Coin coin=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(coin,"id",1L);BestMethodMix mix=new BestMethodMix(coin,900,2,1,List.of("A","B"),List.of(1,1),List.of("A","B"),50,30,35,.5);ReflectionTestUtils.setField(mix,"id",2L);MixTradeSimulation s=new MixTradeSimulation(coin,mix,Direction.UP,2,new BigDecimal("100"),new BigDecimal("0.5"),opened);ReflectionTestUtils.setField(s,"id",3L);return s;}}
